message.content:
{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescuers stand before the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by faded royal banners, the city beyond a maze of broken towers and smoke.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's eye flickers as it casts a beam toward a twisted spire wrapped in black ivy.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "Mara reads her map at a crossroads.",
      "visual_description": "Mara kneels, compass in hand, ink-stained fingers tracing a path past broken fountains and fallen columns.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The Tin Fox scouts a hidden passage.",
      "visual_description": "The small metal fox slips through a gap in a wall, its blue eyes glowing in the darkness.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The Sleeping Tax Collector is found dozing behind a ledger.",
      "visual_description": "Amidst a collapsed archive, the official snores, head on a stack of stamped papers.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "The glass_diver tries to wake the tax collector.",
      "visual_description": "Glass Diver taps the collector's shoulder; only a mumble and a shift of papers respond.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "Mara finds a key in the tax collector's ledger.",
      "visual_description": "Mara carefully lifts the ledger, revealing a brass key stamped with a tower emblem.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The group approaches a magic door in the palace wall.",
      "visual_description": "A shimmering door with shifting runes set into the stone, guarded by two armored patrols frozen in place.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The Oracle Lamp speaks the riddle to open the door.",
      "visual_description": "The lamp's flame leaps, casting shadows that form the riddle's answer on the ground.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The glass_diver unlocks the magic door.",
      "visual_description": "Glass Diver inserts the key; the runes spin, and the door dissolves into a ripple of light.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "They enter a courtyard with a statue and more banners.",
      "visual_description": "Weathered royal banners hang from poles around a cracked statue of a forgotten figure.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "Armored patrols march through the square.",
      "visual_description": "Rows of hollow-eyed figures in rusted armor clank in unison, their visors dark.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The Tin Fox distracts the patrols.",
      "visual_description": "Tin Fox winds its tail and darts between the patrols, leading them away with a metallic clatter.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The glass_diver finds the captured person in a cursed tower.",
      "visual_description": "Inside a circular room, a figure stands frozen in a beam of pale light from a crystal ceiling.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Mara deciphers the curse on the tower floor.",
      "visual_description": "Mara traces symbols on the floor with her compass, the lines glowing as she works.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The Oracle Lamp warns of a collapsing bridge.",
      "visual_description": "The lamp's eye shows a vision of a stone bridge cracking over a chasm.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the bridge.",
      "visual_description": "Stones fall as they run, the glass_diver leading the rescued figure, Mara and Tin Fox close behind.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They escape beyond the ruined city.",
      "visual_description": "The bridge collapses behind them; they stand on safe ground, the city's towers silhouetted against a red sky.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ]
}

